# Clean seal: keep reddish pixels, make non-red transparent; expand logo bbox a bit
swift /tmp/extract_assets.swift >/dev/null
swift -e '
import Foundation
import CoreGraphics
import ImageIO
import UniformTypeIdentifiers

func load(_ path: String) -> CGImage {
  let url = URL(fileURLWithPath: path) as CFURL
  let src = CGImageSourceCreateWithURL(url, nil)!
  return CGImageSourceCreateImageAtIndex(src, 0, nil)!
}
func save(_ img: CGImage, _ path: String) {
  let dest = CGImageDestinationCreateWithURL(URL(fileURLWithPath: path) as CFURL, UTType.png.identifier as CFString, 1, nil)!
  CGImageDestinationAddImage(dest, img, nil)
  CGImageDestinationFinalize(dest)
}

// Clean seal - remove dark/black text overlay
let seal = load("/tmp/seal_crop.png")
let w = seal.width, h = seal.height
let cs = CGColorSpaceCreateDeviceRGB()
let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w*4, space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue)!
ctx.draw(seal, in: CGRect(x:0,y:0,width:w,height:h))
let data = ctx.data!.assumingMemoryBound(to: UInt8.self)
for i in 0..<(w*h) {
  let o = i*4
  let r = Int(data[o]), g = Int(data[o+1]), b = Int(data[o+2])
  // keep only reddish ink; clear black text and near-white
  let isInkRed = r > 120 && r > g + 25 && r > b + 25
  if !isInkRed {
    data[o]=0; data[o+1]=0; data[o+2]=0; data[o+3]=0
  }
}
let cleaned = ctx.makeImage()!
save(cleaned, "/tmp/seal_clean.png")

// Better logo: from full page around detected red logo area (268,137)-(425,179) with more padding left for bird emblem
let full = load("/tmp/orig_full.png")
// expand left significantly - bird emblem is left of text
if let logo = full.cropping(to: CGRect(x: 200, y: 110, width: 280, height: 90)) {
  save(logo, "/Users/mac/Desktop/yangcai_logo.png")
}
save(cleaned, "/Users/mac/Desktop/yangcai_seal.png")
print("assets ready", cleaned.width, cleaned.height)
'
